window.INDEX = [{"id":"button","name":"Button","category":"actions","description":"The standard action control. Exactly one primary button per view; everything else is secondary, ghost or a link.","variants":14,"page":"components/button.html"},{"id":"button-group","name":"Button group","category":"actions","description":"Several controls joined into one object. Two shapes only: a tinted track for choosing one of a set, and a bordered strip for actions that belong together — or, latched, for filters that can be on at once.","variants":15,"page":"components/button-group.html"},{"id":"dropdown","name":"Dropdown menu","category":"actions","description":"A menu of actions anchored to a trigger. Real focus walks the items one tabindex=\"-1\" at a time; destructive items sit last, below a divider.","variants":15,"page":"components/dropdown.html"},{"id":"table","name":"Table","category":"data","description":"Rows of records with a sortable header. The workhorse of every register screen — order lists, GRN lists, ledgers.","variants":5,"page":"components/table.html"},{"id":"data-table","name":"Data table","category":"data","description":"The register screen assembled: a table with a search box, sortable headers, column visibility, row selection and a pager, all running off one array of records.","variants":3,"page":"components/data-table.html"},{"id":"pagination","name":"Pagination","category":"data","description":"Moves through a long register a page at a time, and says where you are in it. The range and the total are the component; the arrows are only what you do about them.","variants":9,"page":"components/pagination.html"},{"id":"stat-card","name":"Stat card","category":"data","description":"One number that matters, with the label above it and the change since the last period below. The tile a dashboard strip is made of, and the answer whenever the data is a single current value rather than a shape.","variants":9,"page":"components/stat-card.html"},{"id":"chart","name":"Chart","category":"data","description":"Chart.js on a canvas, wearing this system's colours. The legend is HTML and doubles as the palette the canvas paints from, so a swatch and the line it names cannot drift apart.","variants":9,"page":"components/chart.html"},{"id":"progress","name":"Progress","category":"data","description":"The determinate wait. A graphite rail filled to the fraction of a known total that is done — receipt against an order, lines closed on a GRN, quantity built against a plan — with the two figures written out beside it.","variants":9,"page":"components/progress.html"},{"id":"empty-state","name":"Empty state","category":"data","description":"What a region shows when it has nothing to draw. Four different situations wearing one shape — nothing created yet, nothing matching the query, nothing this account may see, and nothing that loaded — and the whole job of the component is saying which one it is.","variants":9,"page":"components/empty-state.html"},{"id":"skeleton","name":"Skeleton","category":"data","description":"Grey blocks standing in the exact box the content will occupy — same rows, same leading, same column widths — so the first paint of a screen whose layout is already known lands without moving.","variants":9,"page":"components/skeleton.html"},{"id":"marker","name":"Marker","category":"data","description":"The mark that opens a list item — a dot, a number, an icon or a tinted well — drawn as a real element in a box the height of one line, so it holds its place when the item wraps.","variants":9,"page":"components/marker.html"},{"id":"spinner","name":"Spinner","category":"data","description":"The indeterminate wait. A graphite ring that turns while work of unknown length is in flight, and a line of text that says what the work is.","variants":9,"page":"components/spinner.html"},{"id":"alert","name":"Alert","category":"feedback","description":"An inline notice about the page or the record in front of the user. White card, zinc border, and the only colour is the icon.","variants":9,"page":"components/alert.html"},{"id":"toast","name":"Toast","category":"feedback","description":"A short confirmation that an action the user just took has finished, pushed into a live region pinned to the bottom-left and gone a few seconds later. It reports an outcome; it is never where the outcome is recorded.","variants":9,"page":"components/toast.html"},{"id":"alert-dialog","name":"Alert dialog","category":"feedback","description":"A dialog that interrupts to ask one question with two answers. Unlike a plain dialog it does not dismiss on a backdrop click — the user has to choose.","variants":5,"page":"components/alert-dialog.html"},{"id":"dialog","name":"Dialog","category":"feedback","description":"A centred, dismissible panel over a dimmed page. Use it to take a handful of fields without leaving the list.","variants":3,"page":"components/dialog.html"},{"id":"sheet","name":"Sheet","category":"feedback","description":"A panel that slides in from the right over the page. Shows a record, or the filters for a list, without losing the user's place in it.","variants":2,"page":"components/sheet.html"},{"id":"drawer","name":"Drawer","category":"feedback","description":"A panel that rises from the bottom edge, sized to its content and capped short of the viewport. The phone-shaped place to put a short action list or a quick filter, because the bottom of the screen is where the thumb already is.","variants":3,"page":"components/drawer.html"},{"id":"badge","name":"Badge","category":"feedback","description":"A small pill that labels a record — status, tag or count. Every pill is the same graphite shape; a 6px dot carries the colour.","variants":9,"page":"components/badge.html"},{"id":"tooltip","name":"Tooltip","category":"feedback","description":"A short dark bubble that names the control under the pointer or under the keyboard. It carries a label and nothing else — no controls, no facts that are not already somewhere the user can reach without hovering.","variants":9,"page":"components/tooltip.html"},{"id":"hovercard","name":"Hovercard","category":"feedback","description":"A card of record detail that opens under a link on hover or focus, after a deliberate delay, and stays open long enough to be read and clicked.","variants":9,"page":"components/hovercard.html"},{"id":"popover","name":"Popover","category":"feedback","description":"A panel of controls anchored to a button and opened by a click. It holds things you focus and operate — a filter, a column list, a date range, a two-field edit — and the page behind it keeps working.","variants":9,"page":"components/popover.html"},{"id":"avatar","name":"Avatar","category":"feedback","description":"Initials in a circle standing in for a person. There are no photographs in this system, so a zinc tint and two letters is the whole thing.","variants":8,"page":"components/avatar.html"},{"id":"label","name":"Label","category":"forms","description":"The name of a control, bound to it with for and id or by wrapping it. The smallest component here, and the one that is most often drawn rather than connected.","variants":9,"page":"components/label.html"},{"id":"field","name":"Field","category":"forms","description":"Label, control, help text and error in one block. This is the unit every form is built from, and the thing that owns the wiring between the four.","variants":9,"page":"components/field.html"},{"id":"input","name":"Input","category":"forms","description":"Single-line text entry. The border lives on the wrapper, not on the control, so an icon, a unit or a clear button sits inside the focus outline instead of beside it.","variants":9,"page":"components/input.html"},{"id":"input-group","name":"Input group","category":"forms","description":"One text field and the things that qualify it — a unit, a currency, a scope select, an action — inside a single bordered enclosure that draws one focus outline for all of them.","variants":9,"page":"components/input-group.html"},{"id":"select","name":"Select","category":"forms","description":"One answer out of a short fixed list. A real <select>, styled through its wrapper the way an input is, and an Alpine listbox only for the rows an <option> cannot hold.","variants":9,"page":"components/select.html"},{"id":"textarea","name":"Textarea","category":"forms","description":"Multi-line text entry. Same bordered wrapper as the input, a height measured in rows, and a counter when there is a limit worth showing.","variants":8,"page":"components/textarea.html"},{"id":"checkbox","name":"Checkbox","category":"forms","description":"An independent on or off — one flag, a set of options, or the row selection a register's bulk actions run on. A real native box wearing accent-zinc-700.","variants":8,"page":"components/checkbox.html"},{"id":"radio","name":"Radio","category":"forms","description":"One of a set, and exactly one. Real native radios wearing accent-zinc-700, where the shared name is the group and the only way to mean none is an option that says so.","variants":8,"page":"components/radio.html"},{"id":"toggle","name":"Toggle","category":"forms","description":"A setting that takes effect the moment it is touched. A real checkbox carrying role=\"switch\", with the track and the thumb beside it painted by peer-checked utilities.","variants":8,"page":"components/toggle.html"},{"id":"combobox","name":"Combobox","category":"forms","description":"A text box that filters a list of records and commits one of them. The typing is a search; what reaches the server is a hidden input under it.","variants":9,"page":"components/combobox.html"},{"id":"attachment","name":"Attachment","category":"forms","description":"The documents hanging off a record — a drop zone over the list of what is already there. Every file shows its type, size, who attached it and when.","variants":8,"page":"components/attachment.html"},{"id":"calendar","name":"Calendar","category":"forms","description":"A month grid for picking a date or a range. Monday-first, tabular figures, and the same graphite selection the rest of the system uses.","variants":8,"page":"components/calendar.html"},{"id":"questionnaire","name":"Questionnaire","category":"forms","description":"A run of questions answered in order on one page — a QC checklist, a vendor assessment, a safety audit. One fieldset per question, the question text as its legend, and three equal tiles carrying the answer so a column of them can be read at a glance.","variants":9,"page":"components/questionnaire.html"},{"id":"app-shell","name":"App shell","category":"layout","description":"The page skeleton: an icon rail that expands to a labelled sidebar, a topbar carrying the hamburger, breadcrumb, command palette and account menu, and a single scrolling main column. Everything else in the app renders inside the main column.","variants":1,"page":"components/app-shell.html"},{"id":"page-header","name":"Page header","category":"layout","description":"The top block of a page: where it sits in the app, what it is, what state it is in, and what you can do to it. One h1 per page and it lives here.","variants":8,"page":"components/page-header.html"},{"id":"card","name":"Card","category":"layout","description":"A bordered white panel that groups one thing. A header names it, the body holds the content, and an optional footer carries totals or actions.","variants":9,"page":"components/card.html"},{"id":"separator","name":"Separator","category":"layout","description":"The rule that divides content. Almost always a border on the thing beside it rather than an element of its own, and almost always silent to a screen reader.","variants":6,"page":"components/separator.html"},{"id":"carousel","name":"Carousel","category":"layout","description":"A horizontal rail of items that snaps one item at a time. CSS scroll snap does the moving; the arrows and the counter are the only JavaScript.","variants":8,"page":"components/carousel.html"},{"id":"list-detail","name":"List and detail","category":"layout","description":"A queue on the left and the record being worked on beside it. Arrow keys walk the list, Enter opens the record into the detail pane, and only the two panes scroll — the page behind them does not move.","variants":7,"page":"components/list-detail.html"},{"id":"form-page","name":"Form page","category":"layout","description":"The layout a create or edit screen uses: one h1, the fields grouped in cards, a validation summary that links to every field that failed, and Save and Cancel where the user can always reach them.","variants":8,"page":"components/form-page.html"},{"id":"auth-page","name":"Auth page","category":"layout","description":"The signed-out screen: one centred card, the fewest fields that will do, and nothing else on the page. Sign in, the second factor after it, and every screen the user lands on when one of the two fails.","variants":8,"page":"components/auth-page.html"},{"id":"error-page","name":"Error page","category":"layout","description":"The whole screen the user gets when the page could not be produced at all. It says what failed in their own terms, whether anything they did was saved, and gives one way back into an application whose navigation is not on this page.","variants":7,"page":"components/error-page.html"},{"id":"tabs","name":"Tabs","category":"navigation","description":"Switches between views of the same record without leaving the page. The panel below changes; the row above is a widget, not a menu, and the keyboard has to know the difference.","variants":8,"page":"components/tabs.html"},{"id":"breadcrumbs","name":"Breadcrumbs","category":"navigation","description":"The path from the section root down to the record on screen. The last crumb says where you are and is not a link.","variants":8,"page":"components/breadcrumbs.html"},{"id":"menubar","name":"Menubar","category":"navigation","description":"A row of menus across the top of a document — File, Edit, View — sharing one tab stop and one keyboard model. A desktop-application affordance, and most internal screens should not have one.","variants":9,"page":"components/menubar.html"},{"id":"navigation-menu","name":"Navigation menu","category":"navigation","description":"A horizontal bar of links to places, some of which open a panel of more links. Every item is an anchor, so the browser's own navigation gestures keep working, and aria-current says which one you are on.","variants":9,"page":"components/navigation-menu.html"},{"id":"sidebar","name":"Sidebar","category":"navigation","description":"The primary navigation panel of the console: a header, grouped menus with counts and submenus, and a footer for the signed-in user. It has three forms — a 256px panel, a 68px icon rail, and an off-canvas sheet over the page.","variants":9,"page":"components/sidebar.html"},{"id":"topbar","name":"Topbar","category":"navigation","description":"The application header above the page content: the sidebar trigger, the context you are working in, what you can search and who you are signed in as. A real <header> holding a named <nav>, sticky over the column and out of the way of everything that opens above it.","variants":9,"page":"components/topbar.html"},{"id":"accordion","name":"Accordion","category":"navigation","description":"Sections of content that collapse to their heading. The heading is a button that toggles the panel below it.","variants":3,"page":"components/accordion.html"},{"id":"collapsible","name":"Collapsible","category":"navigation","description":"One trigger and one panel. The standalone disclosure — show more, an advanced section at the foot of a form, a filter bar that folds away.","variants":8,"page":"components/collapsible.html"},{"id":"command-palette","name":"Command palette","category":"navigation","description":"A ⌘K overlay for jumping to a record or firing an action by typing. It is a shortcut over the navigation, never the only route to something.","variants":1,"page":"components/command-palette.html"}];
